#!/usr/bin/env bun
// Generated by ai-share OpenCode launcher.

import { readFileSync } from "node:fs";
import { isAbsolute, resolve } from "node:path";
import { spawnSync } from "node:child_process";

const MANAGED_BEGIN = "# BEGIN ai-share managed env";
const MANAGED_END = "# END ai-share managed env";

export type AiocRunResult = {
  exitCode: number;
  stdout: string;
  stderr: string;
  error?: string;
};

export function buildAiocEnvironment(
  baseEnv: Readonly<Record<string, string | undefined>>,
  envFileContent: string | undefined,
  platform: NodeJS.Platform = process.platform,
): Record<string, string | undefined> {
  const output = { ...baseEnv };
  if (!envFileContent) return output;
  const normalizeName = platform === "win32" ? (name: string): string => name.toUpperCase() : (name: string) => name;
  const existingNames = new Set(Object.keys(output).map(normalizeName));
  const lines = envFileContent.replaceAll("\r\n", "\n").split("\n");
  const begin = lines.indexOf(MANAGED_BEGIN);
  const end = lines.indexOf(MANAGED_END);
  if (
    begin < 0 ||
    end <= begin ||
    lines.lastIndexOf(MANAGED_BEGIN) !== begin ||
    lines.lastIndexOf(MANAGED_END) !== end
  ) {
    return output;
  }
  for (const line of lines.slice(begin + 1, end)) {
    if (!line || line.startsWith("#")) continue;
    const separator = line.indexOf("=");
    if (separator <= 0) continue;
    const name = line.slice(0, separator);
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(name) || existingNames.has(normalizeName(name))) continue;
    output[name] = parseEnvValue(line.slice(separator + 1));
    existingNames.add(normalizeName(name));
  }
  return output;
}

export function runAioc(
  argv: readonly string[],
  env: Record<string, string | undefined>,
  command = "opencode",
  stdio: "inherit" | "pipe" = "inherit",
): AiocRunResult {
  const result = spawnSync(command, [...argv], {
    env,
    stdio,
    encoding: "utf8",
    shell: false,
  });
  return {
    exitCode: result.status ?? 1,
    stdout: typeof result.stdout === "string" ? result.stdout.trim() : "",
    stderr: typeof result.stderr === "string" ? result.stderr.trim() : "",
    ...(result.error ? { error: result.error.message } : {}),
  };
}

if (import.meta.main) {
  const configDir = resolveOpenCodeConfigDir(Bun.env);
  const envFile = tryReadFile(resolve(configDir, ".env"));
  const result = runAioc(Bun.argv.slice(2), buildAiocEnvironment(Bun.env, envFile));
  if (result.error) console.error(`无法启动 OpenCode：${result.error}`);
  process.exitCode = result.exitCode;
}

function resolveOpenCodeConfigDir(env: Readonly<Record<string, string | undefined>>): string {
  const configured = env.OPENCODE_CONFIG_DIR;
  if (configured !== undefined) {
    if (!configured.trim() || !isAbsolute(configured)) throw new Error("OPENCODE_CONFIG_DIR 必须是非空绝对路径。");
    return resolve(configured);
  }
  const home = env.HOME ?? env.USERPROFILE;
  if (!home?.trim() || !isAbsolute(home)) throw new Error("无法解析 OpenCode 配置目录；请设置 HOME 或 USERPROFILE。");
  return resolve(home, ".config", "opencode");
}

function tryReadFile(path: string): string | undefined {
  try {
    return readFileSync(path, "utf8");
  } catch (error) {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") return undefined;
    throw error;
  }
}

function parseEnvValue(value: string): string {
  if (!value.startsWith('"')) return value;
  const parsed: unknown = JSON.parse(value);
  if (typeof parsed !== "string") throw new Error("aioc managed env 包含非字符串值。");
  return parsed;
}
